mapper.select:
SELECT account_id, password_hash, row_version
FROM password_credential
WHERE account_id = #{accountId}

SELECT failure_count, window_started_at, last_failed_at, locked_until, row_version
FROM login_failure_window
WHERE account_id = #{accountId}

SELECT session_id, account_id, token_digest, status, created_at,
       last_seen_at, idle_expires_at, absolute_expires_at,
       request_id, row_version
FROM user_session
WHERE token_digest = #{tokenDigest}
  AND status = 'ACTIVE'
  AND idle_expires_at > #{at}
  AND absolute_expires_at > #{at}

SELECT grant_id, account_id, expires_at, used_at, row_version
FROM password_reset_grant
WHERE token_digest = #{digest}
  AND used_at IS NULL
  AND expires_at > #{at}

SELECT grant_id, account_id, expires_at, used_at, row_version
FROM password_reset_grant
WHERE token_digest = #{digest}
  AND used_at IS NULL
  AND expires_at > #{at}
FOR UPDATE
